import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom'; // React Router hook to get params
import Header from '../components/header/Header';
import PlaceDetails from '../components/place_details/PlaceDetails';
import Footer from '../components/footer/Footer';
import { fetchPlaceById } from '../api'; // Assuming you have a new function to fetch a single place

const PlacePage = () => {
    const { id } = useParams(); // Get the place ID from the URL
    const [place, setPlace] = useState(null); // State for a single place
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const loadPlace = async () => {
            try {
                const data = await fetchPlaceById(id); // Fetch place by ID
                console.log('Fetched place:', data);
                setPlace(data);
            } catch (error) {
                setError('Failed to load place');
            } finally {
                setLoading(false);
            }
        };

        loadPlace();
    }, [id]); // Re-run effect when `id` changes

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <Header />
            <PlaceDetails place={place} /> {/* Pass the single place */}
            <Footer />
        </div>
    );
};

export default PlacePage;
